jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // ─── GitHub Contents API (same pattern as admin_library_publisher) ───
  function _b64(s) {
    var bytes = new TextEncoder().encode(s);
    var bin = "";
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }
  function _ghGet(pat, repo, branch, filePath) {
    var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
      "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
    return fetch(url, {
      cache: "no-store",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) return r.text().then(function (t) { throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
      return r.json();
    });
  }
  function _ghPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
    var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
    var body = { message: message, content: _b64(contentStr), branch: branch };
    if (existingSha) body.sha = existingSha;
    return fetch(url, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (!r.ok) return r.text().then(function (t) { throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
      return r.json();
    });
  }

  function _pat()    { try { return eli.compat.lsGet("eli_user_github_pat")  || eli.compat.lsGet("eli_alp_pat") || ""; } catch (e) { return ""; } }
  function _repo()   { try { return eli.compat.lsGet("eli_github_repo")      || eli.compat.lsGet("eli_alp_repo") || "apndrewn/eli-data"; } catch (e) { return "apndrewn/eli-data"; } }
  function _branch() { try { return eli.compat.lsGet("eli_github_branch")    || eli.compat.lsGet("eli_alp_branch") || "main"; } catch (e) { return "main"; } }

  // ─── State ───────────────────────────────────────────────────────────
  var _currentTool = null;  // loaded bundle from IDB (snapshot before edits)
  var _draft = null;        // working copy with user's edits
  var _root = null;         // dashboard root element
  // Whether the Push button also writes to IDB. Default false so the push
  // exercises the same CDN propagation path every other install uses
  // (kernel re-fetches on next manifest poll). Toggle persists via
  // localStorage so the choice survives reloads.
  var _pushSaveLocal = (function () {
    try { return eli.compat.lsGet("eli_tas_push_savelocal") === "1"; }
    catch (e) { return false; }
  })();
  // Editor sub-tab: "meta" (existing form fields) or "code" (raw source).
  var _editorTab = "meta";
  // Top-level mode: "tools" / "overrides" / "ordering".
  var _mode = "tools";

  // ─── Render entry ────────────────────────────────────────────────────
  function _show() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    _root = mount;
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.className = "_eli3_tas_root";
    root.innerHTML =
      '<div class="_eli3_tas_bar">' +
        '<button class="_eli3_tas_back" title="Back">←</button>' +
        '<div class="_eli3_tas_title">🛠️ Tool Author Studio</div>' +
        '<div class="_eli3_tas_badge">ADMIN</div>' +
        '<div class="_eli3_tas_modetabs">' +
          '<button class="_eli3_tas_modetab" data-tas-mode="tools">Tools</button>' +
          '<button class="_eli3_tas_modetab" data-tas-mode="overrides">Admin Overrides</button>' +
          '<button class="_eli3_tas_modetab" data-tas-mode="ordering">Default Ordering</button>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_tas_body" id="_eli3_tas_body"></div>';
    var back = root.querySelector("._eli3_tas_back");
    if (back) back.onclick = function () {
      if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
    };
    mount.appendChild(root);
    root.querySelectorAll("[data-tas-mode]").forEach(function (b) {
      b.onclick = function () { _mode = b.getAttribute("data-tas-mode"); _renderMode(); };
    });
    _renderMode();
  }
  function _renderMode() {
    // Toggle active style on the mode tabs.
    document.querySelectorAll("[data-tas-mode]").forEach(function (b) {
      b.classList.toggle("active", b.getAttribute("data-tas-mode") === _mode);
    });
    var body = document.getElementById("_eli3_tas_body");
    if (!body) return;
    if (_mode === "tools") {
      body.innerHTML =
        '<div class="_eli3_tas_picker_wrap">' +
          '<div class="_eli3_tas_eyebrow">SELECT A TOOL TO EDIT</div>' +
          '<div class="_eli3_tas_picker" id="_eli3_tas_picker"></div>' +
        '</div>' +
        '<div id="_eli3_tas_editor" class="_eli3_tas_editor_wrap"></div>';
      _renderPicker();
      // Restore editor if user had a tool loaded before switching modes.
      if (_draft) _renderEditor();
    } else if (_mode === "overrides") {
      _renderOverridesMode(body);
    } else if (_mode === "ordering") {
      _renderOrderingMode(body);
    }
  }

  // ─── Tool picker (grid of installed tools) ───────────────────────────
  function _renderPicker() {
    var host = document.getElementById("_eli3_tas_picker");
    if (!host) return;
    host.innerHTML = '<div class="_eli3_tas_loading">Loading installed tools…</div>';
    eli.tools.list().then(function (tools) {
      var safe = (tools || []).filter(function (t) {
        return t && t.id && String(t.id).charAt(0) !== "_";
      }).sort(function (a, b) {
        var la = (a.label || a.id).toLowerCase();
        var lb = (b.label || b.id).toLowerCase();
        return la.localeCompare(lb);
      });
      if (!safe.length) {
        host.innerHTML = '<div class="_eli3_tas_empty">No tools installed.</div>';
        return;
      }
      var html = safe.map(function (t) {
        var cat = t.catalog || {};
        var icon = cat.icon || "🧩";
        var label = t.label || cat.title || t.id;
        var coreBadge = cat.core ? '<span class="_eli3_tas_chip_core">CORE</span>' : "";
        var hiddenBadge = cat.hidden ? '<span class="_eli3_tas_chip_hidden">HIDDEN</span>' : "";
        var disabledBadge = t.disabled ? '<span class="_eli3_tas_chip_dis">DISABLED</span>' : "";
        return '<button class="_eli3_tas_pick" data-tas-pick="' + _esc(t.id) + '">' +
          '<span class="_eli3_tas_pick_icon">' + _esc(icon) + '</span>' +
          '<span class="_eli3_tas_pick_info">' +
            '<span class="_eli3_tas_pick_label">' + _esc(label) +
              coreBadge + hiddenBadge + disabledBadge +
            '</span>' +
            '<span class="_eli3_tas_pick_meta">' + _esc(t.id) + ' · ' + _esc(t.tier || "demand") + '</span>' +
          '</span>' +
        '</button>';
      }).join("");
      host.innerHTML = html;
      host.querySelectorAll("[data-tas-pick]").forEach(function (b) {
        b.onclick = function () {
          var id = b.getAttribute("data-tas-pick");
          _loadEditor(id);
        };
      });
    }).catch(function (err) {
      host.innerHTML = '<div class="_eli3_tas_empty">Couldn\'t load tools: ' + _esc(err && err.message) + '</div>';
    });
  }

  // ─── Editor ──────────────────────────────────────────────────────────
  function _loadEditor(id) {
    eli.tools.get(id).then(function (bundle) {
      if (!bundle) {
        if (typeof showToast === "function") showToast("Bundle " + id + " not found.", "err");
        return;
      }
      _currentTool = bundle;
      _draft = JSON.parse(JSON.stringify(bundle));
      if (!_draft.catalog) _draft.catalog = {};
      _renderEditor();
    }).catch(function (err) {
      if (typeof showToast === "function") showToast("Load failed: " + (err && err.message), "err");
    });
  }

  function _renderEditor() {
    var host = document.getElementById("_eli3_tas_editor");
    if (!host) return;
    var d = _draft;
    var c = d.catalog || {};
    var bodyHtml = (_editorTab === "code") ? _renderCodeTab() : _renderMetaTab();
    host.innerHTML =
      '<div class="_eli3_tas_editor">' +
        '<div class="_eli3_tas_editor_head">' +
          '<div class="_eli3_tas_editor_icon">' + _esc(c.icon || "🧩") + '</div>' +
          '<div class="_eli3_tas_editor_title">' + _esc(d.label || c.title || d.id) + '</div>' +
          '<button class="_eli3_tas_editor_close" title="Close">×</button>' +
        '</div>' +
        '<div class="_eli3_tas_editor_meta">' +
          'ID: <code>' + _esc(d.id) + '</code>' +
          (d.releasedAt ? ' · Released: ' + _esc(String(d.releasedAt).slice(0, 19)) : '') +
        '</div>' +
        '<div class="_eli3_tas_subtabs">' +
          '<button class="_eli3_tas_subtab' + (_editorTab === "meta" ? " active" : "") + '" data-tas-subtab="meta">📋 Metadata</button>' +
          '<button class="_eli3_tas_subtab' + (_editorTab === "code" ? " active" : "") + '" data-tas-subtab="code">📝 Code (engine / view / init / css)</button>' +
        '</div>' +
        bodyHtml;
    host.querySelector("._eli3_tas_editor_close").onclick = function () {
      _currentTool = null;
      _draft = null;
      host.innerHTML = "";
    };
    host.querySelectorAll("[data-tas-subtab]").forEach(function (t) {
      t.onclick = function () {
        if (_editorTab === t.getAttribute("data-tas-subtab")) return;
        _commitDraft();
        _editorTab = t.getAttribute("data-tas-subtab");
        _renderEditor();
      };
    });
    _wireEditorBody(host);
  }
  function _renderMetaTab() {
    var d = _draft;
    var c = d.catalog || {};
    return (
      _section("Identity", [
        _field("catalog.title",  "Tile title — THIS IS WHAT USERS SEE ON THE DASHBOARD",       c.title || "",       "text"),
        _field("label",          "Internal label (tool.label) — used in logs / activity feed only",   d.label || "",       "text"),
        _field("catalog.icon",   "Icon (emoji or text)",         c.icon  || "",       "text"),
        _field("catalog.desc",   "Description",                  c.desc  || "",       "textarea"),
        _field("catalog.hoverTip","Hover tooltip",               c.hoverTip || "",    "text"),
        _field("catalog.category","Category",                    c.category || "Tools - ELI Core", "text"),
      ]) +
      _section("Surface & Order", [
        _bool("catalog.core",    "Core tool (always pinned at top)",   !!c.core),
        _bool("catalog.default", "Default — auto-pin on first run",     c.default !== false),
        _bool("catalog.hidden",  "Hidden — no dashboard tile",          !!c.hidden),
        _field("catalog.order",  "Sort order (lower = earlier)",         c.order != null ? c.order : 999, "number"),
        _select("tier", "Tier (load timing)", d.tier || "demand", ["boot", "preload", "demand"]),
        _bool("disabled",          "Disabled (loaded but hidden + non-launching)", !!d.disabled),
        _bool("defaultEnabled",    "Default enabled on install",                    d.defaultEnabled !== false),
      ]) +
      _section("Micro-label", [
        _field("catalog.microLabel",      "Micro-label text (e.g. ESSENTIAL)",   c.microLabel || "", "text"),
        _select("catalog.microLabelStyle","Micro-label style",                   c.microLabelStyle || "", ["", "gold", "silver", "neutral"]),
        _select("catalog.microLabelVariant","Micro-label variant (legacy)",      c.microLabelVariant || "", ["", "gold", "silver"]),
      ]) +
      _section("Behavior", [
        _bool("catalog.requiresApiKey",   "Requires Gemini API key",  !!c.requiresApiKey),
        _bool("catalog.requiresFooterDoc","Requires footer document", !!c.requiresFooterDoc),
        _bool("catalog.experimental",     "Experimental",              !!c.experimental),
        _field("catalog.statKey",         "Stat key (usage telemetry)", c.statKey || "", "text"),
        _field("catalog.gearChannel",     "Gear icon dispatch channel", c.gearChannel || "", "text"),
        _field("catalog.gearKey",         "Gear icon dispatch key",     c.gearKey || "", "text"),
      ]) +
      _section("Audience", [
        _field("audience",              "Audience tags (comma-separated)", (d.audience || []).join(", "), "text"),
        _field("audienceEmails",        "Audience emails (comma-separated allow-list)", (d.audienceEmails || []).join(", "), "text"),
        _field("audienceEmailDomains",  "Audience email domains (comma-separated)", (d.audienceEmailDomains || []).join(", "), "text"),
        _field("catalog.tags",          "Tags (comma-separated)", (c.tags || []).join(", "), "text"),
      ]) +
      _editorActions()
    );
  }

  function _editorActions() {
    return (
      '<div class="_eli3_tas_actions">' +
        '<button class="_eli3_tas_btn _eli3_tas_btn_secondary" data-tas-action="reset">↺ Reset to installed</button>' +
        '<button class="_eli3_tas_btn _eli3_tas_btn_secondary" data-tas-action="export">📋 Copy bundle JSON</button>' +
        '<button class="_eli3_tas_btn _eli3_tas_btn_secondary" data-tas-action="save">💾 Save locally</button>' +
        '<button class="_eli3_tas_btn _eli3_tas_btn_primary" data-tas-action="push">⬆️ Push to CDN</button>' +
      '</div>' +
      '<label class="_eli3_tas_push_opt">' +
        '<input type="checkbox" id="_eli3_tas_savelocal" ' + (_pushSaveLocal ? "checked" : "") + '>' +
        '<span>Also save locally on push</span>' +
        '<small>Off (recommended): tests the real CDN propagation path. On: writes IDB too so this machine has the edit immediately, but kernel won\'t re-fetch from CDN since timestamps match.</small>' +
      '</label>' +
      '<div id="_eli3_tas_pushlog" class="_eli3_tas_pushlog" style="display:none"></div>'
    );
  }

  // Static code editor — shows the eval'd source for every function
  // bucket on the bundle. Edits write directly to the engine/view/init/
  // simple/css strings on _draft; push goes straight to CDN like any
  // other field edit. No AI, no transformation — the bundle the user
  // sees here is the bundle the next install will get.
  function _renderCodeTab() {
    var d = _draft;
    var html = "";
    html += '<div class="_eli3_tas_codenote">⚠ Editing raw source pushes verbatim to CDN. Use the toggle below to test locally first.</div>';
    if (d.engine && typeof d.engine === "object") {
      Object.keys(d.engine).forEach(function (fn) {
        html += _codeBlock("engine." + fn, "engine." + fn + "  (returns engine fn)", d.engine[fn] || "");
      });
    }
    if (d.view && typeof d.view === "object") {
      Object.keys(d.view).forEach(function (fn) {
        html += _codeBlock("view." + fn, "view." + fn + "  (returns view fn)", d.view[fn] || "");
      });
    }
    if (typeof d.init === "string") {
      html += _codeBlock("init", "init  (runs once at load; receives eli registry)", d.init || "");
    }
    if (typeof d.simple === "string") {
      html += _codeBlock("simple", "simple  (single-fn tool)", d.simple || "");
    }
    if (d.functions && typeof d.functions === "object") {
      Object.keys(d.functions).forEach(function (fn) {
        html += _codeBlock("functions." + fn, "functions." + fn + "  (v2 flat function)", d.functions[fn] || "");
      });
    }
    if (typeof d.css === "string") {
      html += _codeBlock("css", "css  (injected as <style>)", d.css || "");
    }
    if (!html.trim().startsWith("<textarea")) {
      // (it'll always start with the codenote — keep simple guard against empty bundle)
    }
    if (!d.engine && !d.view && !d.init && !d.simple && !d.functions && !d.css) {
      html += '<div class="_eli3_tas_empty">No editable source on this bundle.</div>';
    }
    html += _editorActions();
    return html;
  }
  function _codeBlock(key, label, value) {
    return '<div class="_eli3_tas_codeblock">' +
      '<div class="_eli3_tas_codelabel">' + _esc(label) + '  <span class="_eli3_tas_codekey">' + _esc(key) + '</span></div>' +
      '<textarea class="_eli3_tas_codearea" data-tas-key="' + _esc(key) + '" spellcheck="false">' + _esc(value) + '</textarea>' +
    '</div>';
  }

  function _wireEditorBody(host) {
    host.querySelectorAll("[data-tas-action]").forEach(function (b) {
      b.onclick = function () {
        var action = b.getAttribute("data-tas-action");
        if (action === "reset") {
          if (!_currentTool) return;
          _draft = JSON.parse(JSON.stringify(_currentTool));
          if (!_draft.catalog) _draft.catalog = {};
          _renderEditor();
        } else if (action === "export") {
          _copyToClipboard(JSON.stringify(_buildBundleJson(), null, 2)).then(function () {
            if (typeof showToast === "function") showToast("✅ Bundle JSON copied to clipboard", "ok");
          });
        } else if (action === "save") {
          _commitDraft();
          _saveLocal().then(function () {
            if (typeof showToast === "function") showToast("✅ Saved locally · refresh dashboard to see changes", "ok");
            if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
          }).catch(function (err) {
            if (typeof showToast === "function") showToast("Save failed: " + (err && err.message), "err");
          });
        } else if (action === "push") {
          _commitDraft();
          _saveAndPush();
        }
      };
    });
    host.querySelectorAll("[data-tas-key]").forEach(function (el) {
      el.addEventListener("change", _commitDraft);
      el.addEventListener("input",  _commitDraft);
    });
    var savelocalChk = host.querySelector("#_eli3_tas_savelocal");
    if (savelocalChk) {
      savelocalChk.onchange = function () {
        _pushSaveLocal = !!savelocalChk.checked;
        try { eli.compat.lsSet("eli_tas_push_savelocal", _pushSaveLocal ? "1" : "0"); } catch (e) {}
      };
    }
  }

  // ─── Field renderers ────────────────────────────────────────────────
  function _section(title, rowsHtml) {
    return '<div class="_eli3_tas_section">' +
      '<div class="_eli3_tas_section_head">' + _esc(title) + '</div>' +
      '<div class="_eli3_tas_section_body">' + rowsHtml.join("") + '</div>' +
    '</div>';
  }
  function _field(key, label, value, type) {
    var input;
    if (type === "textarea") {
      input = '<textarea class="_eli3_tas_input" data-tas-key="' + _esc(key) + '" rows="2">' + _esc(value) + '</textarea>';
    } else {
      var t = type || "text";
      input = '<input class="_eli3_tas_input" type="' + t + '" data-tas-key="' + _esc(key) + '" value="' + _esc(value) + '">';
    }
    return '<div class="_eli3_tas_row">' +
      '<label class="_eli3_tas_label">' + _esc(label) + '</label>' +
      input +
    '</div>';
  }
  function _bool(key, label, checked) {
    return '<div class="_eli3_tas_row _eli3_tas_row_bool">' +
      '<label class="_eli3_tas_bool_label">' +
        '<input type="checkbox" class="_eli3_tas_input" data-tas-key="' + _esc(key) + '" data-tas-bool="1"' + (checked ? " checked" : "") + '>' +
        '<span>' + _esc(label) + '</span>' +
      '</label>' +
    '</div>';
  }
  function _select(key, label, value, options) {
    var opts = options.map(function (o) {
      return '<option value="' + _esc(o) + '"' + (o === value ? " selected" : "") + '>' + (_esc(o) || "—") + '</option>';
    }).join("");
    return '<div class="_eli3_tas_row">' +
      '<label class="_eli3_tas_label">' + _esc(label) + '</label>' +
      '<select class="_eli3_tas_input" data-tas-key="' + _esc(key) + '" data-tas-select="1">' + opts + '</select>' +
    '</div>';
  }

  // ─── Commit DOM input values back into _draft ───────────────────────
  function _commitDraft() {
    if (!_draft) return;
    document.querySelectorAll("[data-tas-key]").forEach(function (el) {
      var key = el.getAttribute("data-tas-key");
      var isBool = el.getAttribute("data-tas-bool") === "1";
      var isNum  = el.type === "number";
      var v;
      if (isBool) v = el.checked;
      else if (isNum) { v = el.value === "" ? null : Number(el.value); }
      else v = el.value;
      // Comma-separated list keys → array.
      if (["audience", "audienceEmails", "audienceEmailDomains", "catalog.tags"].indexOf(key) !== -1) {
        v = String(v || "").split(",").map(function (s) { return s.trim(); }).filter(Boolean);
      }
      _setPath(_draft, key, v);
    });
  }
  function _setPath(obj, path, value) {
    var parts = String(path).split(".");
    var cur = obj;
    for (var i = 0; i < parts.length - 1; i++) {
      var k = parts[i];
      if (!cur[k] || typeof cur[k] !== "object") cur[k] = {};
      cur = cur[k];
    }
    var last = parts[parts.length - 1];
    if (value === "" || value == null) {
      // Empty strings → unset for catalog-level optional fields. Booleans
      // and arrays stay as-is.
      if (typeof value === "string" || value == null) {
        if (last === "microLabel" || last === "microLabelStyle" || last === "microLabelVariant" ||
            last === "statKey" || last === "gearChannel" || last === "gearKey" ||
            last === "hoverTip") {
          cur[last] = null;
          return;
        }
      }
    }
    cur[last] = value;
  }

  // ─── Persist + push ─────────────────────────────────────────────────
  function _buildBundleJson() {
    // Mirrors the build_tool.js / release_tools.js output shape so the
    // pushed file is interchangeable with one built locally.
    var d = _draft;
    var bundle = JSON.parse(JSON.stringify(d));
    // Stamp a fresh releasedAt so consumers see this as newer.
    bundle.releasedAt = new Date().toISOString();
    return {
      schemaVersion: 1,
      releasedAt: bundle.releasedAt,
      sectionVersions: { jsonTools: 1 },
      sections: { jsonTools: [bundle] },
    };
  }

  function _saveLocal() {
    if (!_draft) return Promise.reject(new Error("no draft"));
    // Match what evalBundle expects from IDB — store the bundle directly.
    var bundle = JSON.parse(JSON.stringify(_draft));
    bundle.releasedAt = new Date().toISOString();
    return eli.storage.put("json_tools", bundle).then(function () {
      if (eli.tools && eli.tools._loaded) {
        var prev = eli.tools._loaded[bundle.id] || {};
        // Detect whether the code-tab actually touched source. If so, drop
        // the stale eval'd fn maps so evalBundle re-evaluates from the new
        // source on next reload. Otherwise (pure metadata edit) preserve
        // the eval cache so the tool keeps working without a reload.
        var prevEngineSrc = JSON.stringify((prev && prev.engine) || {});
        var newEngineSrc  = JSON.stringify(bundle.engine || {});
        var prevViewSrc   = JSON.stringify((prev && prev.view) || {});
        var newViewSrc    = JSON.stringify(bundle.view || {});
        var prevSimpleSrc = String((prev && prev.simple) || "");
        var newSimpleSrc  = String(bundle.simple || "");
        var prevInitSrc   = String((prev && prev.init) || "");
        var newInitSrc    = String(bundle.init || "");
        var sourceChanged = (
          prevEngineSrc !== newEngineSrc ||
          prevViewSrc   !== newViewSrc   ||
          prevSimpleSrc !== newSimpleSrc ||
          prevInitSrc   !== newInitSrc
        );
        if (!sourceChanged) {
          bundle._eliEngineFns = prev._eliEngineFns;
          bundle._eliViewFns   = prev._eliViewFns;
          bundle._eliSimple    = prev._eliSimple;
        }
        eli.tools._loaded[bundle.id] = bundle;
        if (sourceChanged && typeof showToast === "function") {
          showToast("Source edited — reload the taskpane to re-eval " + bundle.id, "info");
        }
      }
      return bundle;
    });
  }

  function _saveAndPush() {
    var logEl = document.getElementById("_eli3_tas_pushlog");
    function _log(msg, cls) {
      if (logEl) {
        logEl.style.display = "block";
        logEl.innerHTML += '<div class="_eli3_tas_pushlog_line' + (cls ? ' ' + cls : '') + '">' + msg + '</div>';
        logEl.scrollTop = logEl.scrollHeight;
      }
    }
    if (logEl) logEl.innerHTML = "";
    var pat = _pat();
    if (!pat) {
      _log('⚠ No GitHub PAT in localStorage (eli_user_github_pat). Set one via Settings → Import Credentials.', "_eli3_tas_pushlog_err");
      return;
    }
    var repo = _repo(), branch = _branch();
    var bundle = _draft;
    if (!bundle || !bundle.id) {
      _log('❌ No draft loaded — open a tool in the editor first.', "_eli3_tas_pushlog_err");
      return;
    }
    // Stamp the canonical releasedAt ONCE and reuse everywhere — was stale
    // because _buildBundleJson stamped only its clone, then manifest read
    // _draft.releasedAt (unchanged).
    var nowIso = new Date().toISOString();
    bundle.releasedAt = nowIso;
    var bundleJson = _buildBundleJson();
    var bundleJsonStr = JSON.stringify(bundleJson, null, 2);
    var isV3 = !!(bundle.engine || bundle.view || bundle.init || bundle.advertises);
    var filename = bundle.id + (isV3 ? "-v3.json" : ".json");
    var manifestFilename = isV3 ? "tools-manifest-v3.json" : "tools-manifest-v2.json";
    _log('🔑 PAT present (' + pat.length + ' chars), repo <code>' + _esc(repo) + '</code> branch <code>' + _esc(branch) + '</code>');
    _log('📦 Bundle <code>' + _esc(bundle.id) + '</code> · ' + bundleJsonStr.length + ' bytes · releasedAt <code>' + _esc(nowIso) + '</code>');
    _log(_pushSaveLocal
      ? 'ℹ Also-save-locally is ON — this machine will use the IDB copy; kernel won\'t re-fetch from CDN.'
      : 'ℹ Also-save-locally is OFF — this machine will pick up the new bundle from CDN on next manifest poll (round-trip test).');
    _log('⬆️ Pushing <code>' + _esc(filename) + '</code> to GitHub Contents API…');
    var putSha = null;
    var savePromise = _pushSaveLocal
      ? _saveLocal().then(function () { _log('✓ Saved locally to IDB.'); })
      : Promise.resolve();
    savePromise.then(function () {
      // GET existing bundle file for its SHA.
      return _ghGet(pat, repo, branch, filename);
    }).then(function (existing) {
      var sha = existing && existing.sha;
      _log(sha ? '✓ Found existing on CDN — sha ' + sha.slice(0, 8) + '…' : 'ℹ Not present on CDN — creating new');
      var msg = "tool_author_studio: " + bundle.id + " — pushed " + nowIso;
      return _ghPut(pat, repo, branch, filename, bundleJsonStr, msg, sha);
    }).then(function (putRes) {
      putSha = putRes && putRes.content && putRes.content.sha;
      var commitSha = putRes && putRes.commit && putRes.commit.sha;
      _log('✓ Bundle pushed' + (putSha ? ' — new file sha ' + putSha.slice(0, 8) + '…' : '') + (commitSha ? ' · commit ' + commitSha.slice(0, 8) + '…' : ''));
      _log('⬆️ Updating manifest entry…');
      return _ghGet(pat, repo, branch, manifestFilename);
    }).then(function (manifestRes) {
      if (!manifestRes) throw new Error("Manifest not found at " + manifestFilename);
      var b64 = (manifestRes.content || "").replace(/\s/g, "");
      var bytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
      var manifestStr = new TextDecoder().decode(bytes);
      var manifest = JSON.parse(manifestStr);
      var entry = (manifest.tools || []).find(function (t) { return t.id === bundle.id; });
      if (!entry) {
        entry = {
          id: bundle.id,
          version: bundle.__version || null,
          lastUpdated: nowIso,
          filename: filename,
          size: bundleJsonStr.length,
          label: bundle.label || bundle.id,
          kind: "tool",
          category: (bundle.catalog && bundle.catalog.category) || "Tools - ELI Core",
          audience: bundle.audience || ["all"],
          changelog: "",
        };
        if (bundle.audienceEmails && bundle.audienceEmails.length) entry.audienceEmails = bundle.audienceEmails;
        if (bundle.audienceEmailDomains && bundle.audienceEmailDomains.length) entry.audienceEmailDomains = bundle.audienceEmailDomains;
        manifest.tools = manifest.tools || [];
        manifest.tools.push(entry);
        _log('  ℹ Synthesized new manifest entry');
      } else {
        entry.lastUpdated = nowIso;
        entry.size = bundleJsonStr.length;
        entry.label = bundle.label || bundle.id;
        entry.category = (bundle.catalog && bundle.catalog.category) || entry.category;
        entry.audience = bundle.audience || entry.audience || ["all"];
        if (bundle.audienceEmails && bundle.audienceEmails.length) entry.audienceEmails = bundle.audienceEmails;
        else delete entry.audienceEmails;
        if (bundle.audienceEmailDomains && bundle.audienceEmailDomains.length) entry.audienceEmailDomains = bundle.audienceEmailDomains;
        else delete entry.audienceEmailDomains;
      }
      manifest.lastUpdated = nowIso;
      var manifestJsonStr = JSON.stringify(manifest, null, 2);
      return _ghPut(pat, repo, branch, manifestFilename, manifestJsonStr,
        "tool_author_studio: bump " + bundle.id + " in manifest", manifestRes.sha);
    }).then(function () {
      _log('✓ Manifest pushed.');
      // Force jsdelivr to refresh its edge cache. Public, no-auth, no-CORS
      // endpoint. Without this the user sees stale content for 12+ hours.
      _log('🧹 Purging jsdelivr CDN cache…');
      var purgeBundle  = "https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filename;
      var purgeMfst    = "https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + manifestFilename;
      return Promise.all([
        fetch(purgeBundle, { cache: "no-store" }).then(function (r) { return r.ok; }, function () { return false; }),
        fetch(purgeMfst,   { cache: "no-store" }).then(function (r) { return r.ok; }, function () { return false; }),
      ]).then(function (results) {
        _log('  bundle purge: ' + (results[0] ? '✓' : '⚠') + ' · manifest purge: ' + (results[1] ? '✓' : '⚠'));
      });
    }).then(function () {
      // Verification step — fetch the file back via jsdelivr (post-purge)
      // and confirm the releasedAt matches what we just pushed.
      _log('🔍 Verifying via jsdelivr…');
      var rawUrl = "https://cdn.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filename + "?t=" + Date.now();
      return fetch(rawUrl, { cache: "no-store" }).then(function (r) {
        if (!r.ok) {
          _log('⚠ jsdelivr fetch returned HTTP ' + r.status + ' — content was pushed but CDN cache may take a few minutes', "_eli3_tas_pushlog_err");
          return null;
        }
        return r.text();
      }).then(function (text) {
        if (!text) return;
        try {
          var verifyJson = JSON.parse(text);
          var verifyTool = verifyJson.sections && verifyJson.sections.jsonTools && verifyJson.sections.jsonTools[0];
          var verifyTs = verifyTool && verifyTool.releasedAt;
          if (verifyTs === nowIso) {
            _log('✓ jsdelivr serves the new releasedAt — propagation confirmed.', "_eli3_tas_pushlog_ok");
          } else {
            _log('⚠ jsdelivr still serves <code>' + _esc(String(verifyTs)) + '</code> (expected <code>' + _esc(nowIso) + '</code>) — purge may take 10–60 s to propagate across edges. Re-check shortly.', "_eli3_tas_pushlog_err");
          }
        } catch (_parseErr) {
          _log('⚠ jsdelivr response not parseable — push reached GitHub.', "_eli3_tas_pushlog_err");
        }
      });
    }).then(function () {
      _log('✅ Done — <b>' + _esc(bundle.id) + '</b> live on CDN', "_eli3_tas_pushlog_ok");
      if (typeof showToast === "function") showToast("✅ " + bundle.id + " pushed to CDN", "ok");
    }).catch(function (err) {
      _log('❌ ' + _esc(err && err.message || "unknown error"), "_eli3_tas_pushlog_err");
      if (typeof showToast === "function") showToast("Push failed: " + (err && err.message), "err");
    });
  }

  function _copyToClipboard(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(function () { return _copyFallback(text); });
    }
    return _copyFallback(text);
  }
  function _copyFallback(text) {
    return new Promise(function (resolve, reject) {
      var ta = document.createElement("textarea");
      ta.value = text;
      ta.style.cssText = "position:fixed;left:-9999px;opacity:0";
      document.body.appendChild(ta);
      ta.select();
      var ok = false;
      try { ok = document.execCommand("copy"); } catch (e) {}
      document.body.removeChild(ta);
      ok ? resolve() : reject(new Error("clipboard blocked"));
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // Admin Overrides mode
  // ═══════════════════════════════════════════════════════════════════
  // Pushes admin-overrides.json to the eli-data CDN repo. The kernel
  // polls that file alongside the tools manifest, applies actions on
  // boot, marks applied IDs in IDB so they never re-run. See CLAUDE.md
  // "Admin remote-control" for the full action vocabulary.

  var _overrides = null;  // currently-loaded overrides object
  var _overridesSha = null;

  function _renderOverridesMode(body) {
    body.innerHTML =
      '<div class="_eli3_tas_admin_wrap">' +
        '<div class="_eli3_tas_admin_intro">' +
          '<div class="_eli3_tas_admin_eyebrow">REMOTE CONTROL</div>' +
          '<div class="_eli3_tas_admin_title">Admin Overrides</div>' +
          '<div class="_eli3_tas_admin_desc">' +
            'The kernel polls <code>admin-overrides.json</code> on the CDN every manifest cycle. ' +
            'Each entry in <code>overrides[]</code> has a unique id, an audience filter, an optional expiresAt, ' +
            'and an actions[] list. Actions run on the user\'s machine and the kernel writes a marker into ' +
            '<code>STORE_CONFIG._admin_applied_&lt;id&gt;</code> so the same action never re-runs. ' +
            'Read-back actions (request_stats_dump, etc.) prompt the user for consent first — no silent exfiltration.' +
          '</div>' +
          '<div class="_eli3_tas_admin_actions_help">' +
            '<b>Common actions:</b> ' +
            '<code>disable_tool</code> · <code>enable_tool</code> · <code>force_redownload_tool</code> · ' +
            '<code>clear_idb_row</code> · <code>clear_localstorage_key</code> · <code>set_config</code> · ' +
            '<code>reset_onboarding</code> · <code>notice</code> (message users) · <code>reload_kernel</code>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_tas_admin_split">' +
          '<div class="_eli3_tas_admin_left">' +
            '<div class="_eli3_tas_eyebrow">CURRENT OVERRIDES ON CDN</div>' +
            '<div id="_eli3_tas_admin_list" class="_eli3_tas_admin_list">Loading…</div>' +
          '</div>' +
          '<div class="_eli3_tas_admin_right">' +
            '<div class="_eli3_tas_eyebrow">COMPOSE NEW OVERRIDE</div>' +
            _renderOverrideComposer() +
          '</div>' +
        '</div>' +
        '<div id="_eli3_tas_pushlog" class="_eli3_tas_pushlog" style="display:none"></div>' +
      '</div>';
    _loadOverridesFromCdn();
    _wireOverridesComposer(body);
  }

  function _renderOverrideComposer() {
    var nowMs = Date.now();
    var defaultId = "override-" + new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
    var defaultExpiry = new Date(nowMs + 7 * 24 * 60 * 60 * 1000).toISOString();
    return (
      _section("Identity", [
        _field("__ovr.id",        "Override id (unique, descriptive)", defaultId, "text"),
        _field("__ovr.expiresAt", "Expires at (ISO 8601, optional)",   defaultExpiry, "text"),
      ]) +
      _section("Audience", [
        _field("__ovr.audience",            "Audience tags (comma-sep — \"all\" matches everyone)", "all", "text"),
        _field("__ovr.audienceEmails",      "Specific emails (comma-sep)", "", "text"),
        _field("__ovr.audienceEmailDomains","Email domains (comma-sep)",   "", "text"),
      ]) +
      _section("Quick action — Show notice (message users)", [
        _field("__ovr.noticeTitle",  "Notice title",  "Heads up from Andrew", "text"),
        _field("__ovr.noticeBody",   "Notice body (HTML allowed)", "", "textarea"),
        _bool ("__ovr.noticeRequireAck", "Require explicit acknowledge before dismiss", false),
        _bool ("__ovr.noticeDismissible","Show dismiss button", true),
      ]) +
      _section("Quick action — Tool kill switch", [
        _select("__ovr.toolAction", "Action", "", ["", "disable_tool", "enable_tool", "force_redownload_tool"]),
        _field ("__ovr.toolId",     "Tool id (e.g. review_redlines)", "", "text"),
      ]) +
      _section("Custom actions[] JSON (advanced — overrides the quick actions above)", [
        _field("__ovr.actionsJson",  "Paste raw actions array, e.g. [{\"type\":\"disable_tool\",\"toolId\":\"x\"}]", "", "textarea"),
      ]) +
      '<div class="_eli3_tas_actions">' +
        '<button class="_eli3_tas_btn _eli3_tas_btn_secondary" data-tas-ovr="preview">👁 Preview JSON</button>' +
        '<button class="_eli3_tas_btn _eli3_tas_btn_primary" data-tas-ovr="push">⬆️ Append &amp; Push override</button>' +
      '</div>'
    );
  }

  function _wireOverridesComposer(root) {
    var body = root.querySelector("#_eli3_tas_admin_list").parentElement.parentElement;
    body.querySelectorAll("[data-tas-ovr]").forEach(function (b) {
      b.onclick = function () {
        var op = b.getAttribute("data-tas-ovr");
        var draft = _readOverrideDraftFromForm(body);
        if (op === "preview") {
          var box = body.querySelector("#_eli3_tas_admin_list");
          if (box) {
            box.innerHTML =
              '<div class="_eli3_tas_admin_preview">' +
                '<div class="_eli3_tas_codelabel">Override preview</div>' +
                '<pre>' + _esc(JSON.stringify(draft, null, 2)) + '</pre>' +
                '<button class="_eli3_tas_btn _eli3_tas_btn_secondary" id="_eli3_tas_admin_back">← Back to live list</button>' +
              '</div>';
            var back = box.querySelector("#_eli3_tas_admin_back");
            if (back) back.onclick = function () { _loadOverridesFromCdn(); };
          }
        } else if (op === "push") {
          _pushOverride(draft);
        }
      };
    });
  }

  function _readOverrideDraftFromForm(root) {
    var get = function (key) {
      var el = root.querySelector('[data-tas-key="' + key + '"]');
      if (!el) return "";
      if (el.getAttribute("data-tas-bool") === "1") return !!el.checked;
      return el.value;
    };
    var splitList = function (s) {
      return String(s || "").split(",").map(function (x) { return x.trim(); }).filter(Boolean);
    };
    var actions = [];
    var rawJson = get("__ovr.actionsJson");
    if (rawJson && rawJson.trim()) {
      try { actions = JSON.parse(rawJson); }
      catch (e) {
        if (typeof showToast === "function") showToast("actions JSON invalid: " + e.message, "err");
        return null;
      }
    } else {
      var toolAction = get("__ovr.toolAction");
      var toolId     = get("__ovr.toolId");
      if (toolAction && toolId) actions.push({ type: toolAction, toolId: toolId });
      var nTitle = get("__ovr.noticeTitle");
      var nBody  = get("__ovr.noticeBody");
      if (nBody && nBody.trim()) {
        actions.push({
          type: "notice",
          title: nTitle || "",
          html: nBody,
          dismissible: !!get("__ovr.noticeDismissible"),
          requireAck:  !!get("__ovr.noticeRequireAck"),
        });
      }
    }
    var entry = {
      id: get("__ovr.id") || ("override-" + Date.now()),
      audience: splitList(get("__ovr.audience")),
      actions: actions,
    };
    var emails = splitList(get("__ovr.audienceEmails"));
    var domains = splitList(get("__ovr.audienceEmailDomains"));
    if (emails.length)  entry.audienceEmails = emails;
    if (domains.length) entry.audienceEmailDomains = domains;
    var exp = get("__ovr.expiresAt");
    if (exp && exp.trim()) entry.expiresAt = exp.trim();
    return entry;
  }

  function _loadOverridesFromCdn() {
    var pat = _pat(), repo = _repo(), branch = _branch();
    var list = document.getElementById("_eli3_tas_admin_list");
    if (!list) return;
    list.innerHTML = "Loading…";
    _ghGet(pat, repo, branch, "admin-overrides.json").then(function (res) {
      if (!res) {
        _overrides = { schemaVersion: 1, lastUpdated: new Date().toISOString(), overrides: [] };
        _overridesSha = null;
        list.innerHTML = '<div class="_eli3_tas_empty">No admin-overrides.json on CDN yet — pushing one will create it.</div>';
        return;
      }
      _overridesSha = res.sha;
      var b64 = (res.content || "").replace(/\s/g, "");
      try {
        var bytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
        _overrides = JSON.parse(new TextDecoder().decode(bytes));
      } catch (parseErr) {
        list.innerHTML = '<div class="_eli3_tas_empty">⚠ admin-overrides.json on CDN failed to parse: ' + _esc(parseErr.message) + '</div>';
        _overrides = null;
        return;
      }
      var entries = (_overrides && _overrides.overrides) || [];
      if (!entries.length) {
        list.innerHTML = '<div class="_eli3_tas_empty">No overrides currently published.</div>';
        return;
      }
      list.innerHTML = entries.map(function (o, idx) {
        var audSummary = (o.audience || []).join(", ") +
          (o.audienceEmails ? " · " + o.audienceEmails.length + " email(s)" : "") +
          (o.audienceEmailDomains ? " · " + o.audienceEmailDomains.length + " domain(s)" : "");
        var actsLabel = (o.actions || []).map(function (a) { return a.type; }).join(", ");
        var exp = o.expiresAt ? '<span class="_eli3_tas_admin_exp">expires ' + _esc(String(o.expiresAt).slice(0, 19)) + '</span>' : '';
        return (
          '<div class="_eli3_tas_admin_card">' +
            '<div class="_eli3_tas_admin_card_head"><code>' + _esc(o.id) + '</code> ' + exp + '</div>' +
            '<div class="_eli3_tas_admin_card_aud">' + _esc(audSummary || "(no audience)") + '</div>' +
            '<div class="_eli3_tas_admin_card_acts">' + _esc(actsLabel || "(no actions)") + '</div>' +
            '<button class="_eli3_tas_btn _eli3_tas_btn_secondary _eli3_tas_admin_card_remove" data-tas-ovr-remove="' + idx + '">🗑 Remove</button>' +
          '</div>'
        );
      }).join("");
      list.querySelectorAll("[data-tas-ovr-remove]").forEach(function (b) {
        b.onclick = function () {
          var idx = Number(b.getAttribute("data-tas-ovr-remove"));
          _overrides.overrides.splice(idx, 1);
          _pushOverridesFile();
        };
      });
    }).catch(function (err) {
      list.innerHTML = '<div class="_eli3_tas_empty">Load failed: ' + _esc(err && err.message) + '</div>';
    });
  }

  function _pushOverride(entry) {
    if (!entry || !entry.id || !entry.actions || !entry.actions.length) {
      if (typeof showToast === "function") showToast("Override needs id + at least one action", "err");
      return;
    }
    if (!_overrides) _overrides = { schemaVersion: 1, overrides: [] };
    if (!Array.isArray(_overrides.overrides)) _overrides.overrides = [];
    // Replace existing entry with same id, or append.
    var existing = _overrides.overrides.findIndex(function (o) { return o && o.id === entry.id; });
    if (existing !== -1) _overrides.overrides[existing] = entry;
    else _overrides.overrides.push(entry);
    _pushOverridesFile();
  }

  function _pushOverridesFile() {
    var pat = _pat(), repo = _repo(), branch = _branch();
    if (!pat) {
      if (typeof showToast === "function") showToast("No GitHub PAT in localStorage", "err");
      return;
    }
    _overrides.lastUpdated = new Date().toISOString();
    var jsonStr = JSON.stringify(_overrides, null, 2);
    var logEl = document.getElementById("_eli3_tas_pushlog");
    function _log(msg, cls) {
      if (logEl) {
        logEl.style.display = "block";
        logEl.innerHTML += '<div class="_eli3_tas_pushlog_line' + (cls ? ' ' + cls : '') + '">' + msg + '</div>';
        logEl.scrollTop = logEl.scrollHeight;
      }
    }
    if (logEl) logEl.innerHTML = "";
    _log('⬆️ Pushing admin-overrides.json (' + jsonStr.length + ' bytes) to ' + _esc(repo + "@" + branch) + '…');
    _ghPut(pat, repo, branch, "admin-overrides.json", jsonStr,
      "tool_author_studio: admin-overrides update " + _overrides.lastUpdated, _overridesSha
    ).then(function (res) {
      _overridesSha = res && res.content && res.content.sha;
      _log('✓ Pushed.');
      _log('🧹 Purging jsdelivr cache…');
      return fetch("https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/admin-overrides.json",
        { cache: "no-store" }).then(function () { _log('  purge ✓'); });
    }).then(function () {
      _log('✅ Admin overrides live on CDN.', "_eli3_tas_pushlog_ok");
      if (typeof showToast === "function") showToast("✅ Override pushed", "ok");
      _loadOverridesFromCdn();
    }).catch(function (err) {
      _log('❌ ' + _esc(err && err.message), "_eli3_tas_pushlog_err");
      if (typeof showToast === "function") showToast("Push failed: " + (err && err.message), "err");
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // Default ordering mode
  // ═══════════════════════════════════════════════════════════════════
  // Lists every installed tool with its catalog.order value. Lets the
  // admin bulk-rewrite order numbers. Save writes each tool's bundle
  // back to IDB; Push to CDN republishes each modified bundle.

  function _renderOrderingMode(body) {
    body.innerHTML =
      '<div class="_eli3_tas_admin_wrap">' +
        '<div class="_eli3_tas_admin_intro">' +
          '<div class="_eli3_tas_admin_eyebrow">TILE ORDER</div>' +
          '<div class="_eli3_tas_admin_title">Default Ordering</div>' +
          '<div class="_eli3_tas_admin_desc">' +
            '<code>catalog.order</code> per-tool controls how tiles sort on first-run. ' +
            'Lower numbers appear first. Core tools always pin above non-core regardless of order. ' +
            'Edit the numbers below or use ↑/↓ buttons, then Save to IDB and Push to CDN to apply for every user on next manifest poll.' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_tas_admin_actions">' +
          '<button class="_eli3_tas_btn _eli3_tas_btn_secondary" data-tas-ord="renumber">🔢 Renumber 10-step</button>' +
          '<button class="_eli3_tas_btn _eli3_tas_btn_primary" data-tas-ord="save-push">⬆️ Save &amp; Push all changes</button>' +
        '</div>' +
        '<div id="_eli3_tas_ord_list" class="_eli3_tas_ord_list">Loading…</div>' +
        '<div id="_eli3_tas_pushlog" class="_eli3_tas_pushlog" style="display:none"></div>' +
      '</div>';
    _loadOrderingList(body);
  }

  var _orderingDraft = []; // [{ id, order, label, modified }]

  function _loadOrderingList(root) {
    eli.tools.list().then(function (tools) {
      _orderingDraft = (tools || []).filter(function (t) {
        return t && t.id && String(t.id).charAt(0) !== "_";
      }).map(function (t) {
        var c = t.catalog || {};
        return {
          id: t.id,
          order: (c.order != null) ? Number(c.order) : 999,
          label: t.label || c.title || t.id,
          icon: c.icon || "🧩",
          core: !!c.core,
          hidden: !!c.hidden,
          modified: false,
          bundle: t,
        };
      }).sort(function (a, b) {
        if (a.core !== b.core) return a.core ? -1 : 1;
        return a.order - b.order;
      });
      _renderOrderingList(root);
    }).catch(function (err) {
      var list = root.querySelector("#_eli3_tas_ord_list");
      if (list) list.innerHTML = '<div class="_eli3_tas_empty">Load failed: ' + _esc(err && err.message) + '</div>';
    });
  }

  function _renderOrderingList(root) {
    var list = root.querySelector("#_eli3_tas_ord_list");
    if (!list) return;
    list.innerHTML = _orderingDraft.map(function (e, i) {
      var coreChip = e.core ? '<span class="_eli3_tas_chip_core">CORE</span>' : '';
      var hiddenChip = e.hidden ? '<span class="_eli3_tas_chip_hidden">HIDDEN</span>' : '';
      var modChip = e.modified ? '<span class="_eli3_tas_chip_mod">MODIFIED</span>' : '';
      return (
        '<div class="_eli3_tas_ord_row" data-tas-ord-idx="' + i + '">' +
          '<span class="_eli3_tas_ord_icon">' + _esc(e.icon) + '</span>' +
          '<input class="_eli3_tas_ord_input" type="number" data-tas-ord-input="' + i + '" value="' + e.order + '">' +
          '<span class="_eli3_tas_ord_label">' + _esc(e.label) + ' ' + coreChip + hiddenChip + modChip + '</span>' +
          '<span class="_eli3_tas_ord_id">' + _esc(e.id) + '</span>' +
          '<button class="_eli3_tas_ord_arrow" data-tas-ord-arrow="up:' + i + '" title="Move up">↑</button>' +
          '<button class="_eli3_tas_ord_arrow" data-tas-ord-arrow="down:' + i + '" title="Move down">↓</button>' +
        '</div>'
      );
    }).join("");
    list.querySelectorAll("[data-tas-ord-input]").forEach(function (inp) {
      inp.onchange = function () {
        var idx = Number(inp.getAttribute("data-tas-ord-input"));
        var v = inp.value === "" ? null : Number(inp.value);
        _orderingDraft[idx].order = v != null ? v : 999;
        _orderingDraft[idx].modified = true;
        _orderingDraft.sort(function (a, b) {
          if (a.core !== b.core) return a.core ? -1 : 1;
          return a.order - b.order;
        });
        _renderOrderingList(root);
      };
    });
    list.querySelectorAll("[data-tas-ord-arrow]").forEach(function (b) {
      b.onclick = function () {
        var parts = b.getAttribute("data-tas-ord-arrow").split(":");
        var dir = parts[0], i = Number(parts[1]);
        var j = dir === "up" ? i - 1 : i + 1;
        if (j < 0 || j >= _orderingDraft.length) return;
        // Swap the order values + mark both modified.
        var tmp = _orderingDraft[i].order;
        _orderingDraft[i].order = _orderingDraft[j].order;
        _orderingDraft[j].order = tmp;
        _orderingDraft[i].modified = true;
        _orderingDraft[j].modified = true;
        _orderingDraft.sort(function (a, b) {
          if (a.core !== b.core) return a.core ? -1 : 1;
          return a.order - b.order;
        });
        _renderOrderingList(root);
      };
    });
    var renumber = root.querySelector('[data-tas-ord="renumber"]');
    if (renumber) renumber.onclick = function () {
      _orderingDraft.forEach(function (e, i) {
        var newOrder = (i + 1) * 10;
        if (e.order !== newOrder) { e.order = newOrder; e.modified = true; }
      });
      _renderOrderingList(root);
    };
    var savePush = root.querySelector('[data-tas-ord="save-push"]');
    if (savePush) savePush.onclick = function () { _saveAndPushOrdering(root); };
  }

  function _saveAndPushOrdering(root) {
    var logEl = root.querySelector("#_eli3_tas_pushlog");
    function _log(msg, cls) {
      if (logEl) {
        logEl.style.display = "block";
        logEl.innerHTML += '<div class="_eli3_tas_pushlog_line' + (cls ? ' ' + cls : '') + '">' + msg + '</div>';
        logEl.scrollTop = logEl.scrollHeight;
      }
    }
    if (logEl) logEl.innerHTML = "";
    var modified = _orderingDraft.filter(function (e) { return e.modified; });
    if (!modified.length) {
      _log('Nothing modified.');
      return;
    }
    var pat = _pat(), repo = _repo(), branch = _branch();
    if (!pat) { _log('⚠ No GitHub PAT — set one in Settings.', "_eli3_tas_pushlog_err"); return; }
    _log('📦 ' + modified.length + ' tool(s) modified — saving local + pushing to CDN…');
    var chain = Promise.resolve();
    modified.forEach(function (e) {
      chain = chain.then(function () {
        var bundle = JSON.parse(JSON.stringify(e.bundle));
        if (!bundle.catalog) bundle.catalog = {};
        bundle.catalog.order = e.order;
        var nowIso = new Date().toISOString();
        bundle.releasedAt = nowIso;
        return eli.storage.put("json_tools", bundle).then(function () {
          var isV3 = !!(bundle.engine || bundle.view || bundle.init || bundle.advertises);
          var filename = bundle.id + (isV3 ? "-v3.json" : ".json");
          var bundleJson = {
            schemaVersion: 1,
            releasedAt: nowIso,
            sectionVersions: { jsonTools: 1 },
            sections: { jsonTools: [bundle] },
          };
          var jsonStr = JSON.stringify(bundleJson, null, 2);
          _log('  ⬆️ ' + e.id + ' → order ' + e.order);
          return _ghGet(pat, repo, branch, filename).then(function (existing) {
            var sha = existing && existing.sha;
            return _ghPut(pat, repo, branch, filename, jsonStr,
              "tool_author_studio: reorder " + bundle.id + " → " + e.order, sha);
          }).then(function () {
            return fetch("https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filename, { cache: "no-store" })
              .then(function () { _log('     ✓ pushed + purged'); });
          });
        });
      });
    });
    chain.then(function () {
      _log('✅ All modified tools pushed. Run Tool Manager → Check for updates so other users pick up the new order.', "_eli3_tas_pushlog_ok");
      _orderingDraft.forEach(function (e) { e.modified = false; });
      _renderOrderingList(root);
    }).catch(function (err) {
      _log('❌ ' + _esc(err && err.message), "_eli3_tas_pushlog_err");
    });
  }

  // ─── Register ──────────────────────────────────────────────────────
  eli.register({
    tile: { app_tool_author_studio: _show },
    tool_author_studio: { open: _show },
  });

  eli.log.event("tool", "tool_author_studio_initialized", {});
}

jsonTools.css:
/* tools/tool_author_studio/style.css
 * Premium admin chrome. Two-column layout: tool picker (left) and editor
 * panel (right). Cream gradient background + gold accents matching the
 * welcome / refresh_eli visual language. */

._eli3_tas_root {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  background: linear-gradient(180deg, #ffffff 0%, #faf9ee 100%);
  overflow: hidden;
}
body:has(._eli3_tas_root) #output,
body:has(._eli3_tas_root) #_eli3_dashboard_root {
  overflow: hidden !important;
}

._eli3_tas_bar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_tas_back {
  background: none;
  border: none;
  cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif;
  color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_tas_back:hover { color: #f2d866; }
._eli3_tas_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #fff;
  letter-spacing: 0.2px;
}
._eli3_tas_badge {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #1a1208;
  background: linear-gradient(135deg, #f2d866 0%, #c9a227 100%);
  padding: 4px 8px;
  border-radius: 2px;
}

._eli3_tas_body {
  flex: 1 1 auto;
  display: flex;
  gap: 14px;
  padding: 14px 16px;
  overflow: hidden;
}

._eli3_tas_picker_wrap {
  flex: 0 0 280px;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
._eli3_tas_eyebrow {
  font: 800 9.5px/1 'Inter', sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #a07d12;
  margin-bottom: 8px;
}
._eli3_tas_picker {
  flex: 1 1 auto;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eli3_tas_loading, ._eli3_tas_empty {
  font: 500 12px/1.4 'Inter', sans-serif;
  color: #64748b;
  font-style: italic;
  padding: 14px;
  text-align: center;
}
._eli3_tas_pick {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid transparent;
  cursor: pointer;
  text-align: left;
  font-family: 'Inter', sans-serif;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_tas_pick:hover {
  border-left-color: #c9a227;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.08);
}
._eli3_tas_pick_icon { font-size: 18px; flex-shrink: 0; }
._eli3_tas_pick_info { flex: 1; min-width: 0; }
._eli3_tas_pick_label {
  display: block;
  font: 700 12.5px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-bottom: 2px;
}
._eli3_tas_pick_meta {
  display: block;
  font: 400 10px/1.2 'Inter', sans-serif;
  color: #94a3b8;
  font-family: monospace;
}
._eli3_tas_chip_core, ._eli3_tas_chip_hidden, ._eli3_tas_chip_dis {
  display: inline-block;
  font: 700 8px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 2px 5px;
  margin-left: 6px;
  vertical-align: 1px;
  border-radius: 2px;
}
._eli3_tas_chip_core   { background: #fef3c7; color: #92400e; }
._eli3_tas_chip_hidden { background: #e0e7ff; color: #3730a3; }
._eli3_tas_chip_dis    { background: #fee2e2; color: #b91c1c; }

._eli3_tas_editor_wrap {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
}
._eli3_tas_editor {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #c9a227;
  padding: 0;
}
._eli3_tas_editor_head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  background: linear-gradient(180deg, #faf9ee 0%, #f5f1d9 100%);
  border-bottom: 1px solid #fde68a;
}
._eli3_tas_editor_icon { font-size: 28px; }
._eli3_tas_editor_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #0f172a;
}
._eli3_tas_editor_close {
  background: none;
  border: none;
  cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif;
  color: #94a3b8;
  padding: 0 4px;
}
._eli3_tas_editor_close:hover { color: #0f172a; }
._eli3_tas_editor_meta {
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #64748b;
  padding: 8px 18px;
  border-bottom: 1px solid #f1f5f9;
}
._eli3_tas_editor_meta code {
  font: 600 11px/1 monospace;
  background: #f1f5f9;
  padding: 1px 5px;
  border-radius: 2px;
  color: #1565c0;
}

._eli3_tas_section {
  border-bottom: 1px solid #f1f5f9;
}
._eli3_tas_section:last-of-type { border-bottom: none; }
._eli3_tas_section_head {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #475569;
  padding: 12px 18px 6px;
  background: #fafbfc;
  border-left: 3px solid #c9a227;
}
._eli3_tas_section_body {
  padding: 10px 18px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eli3_tas_row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._eli3_tas_row_bool { margin: 2px 0; }
._eli3_tas_label {
  font: 700 10px/1.2 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #64748b;
}
._eli3_tas_input {
  width: 100%;
  padding: 8px 10px;
  font: 500 12.5px/1.3 'Inter', sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 2px;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_tas_input:focus {
  border-color: #c9a227;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.18);
}
textarea._eli3_tas_input {
  resize: vertical;
  min-height: 56px;
  font-family: 'Inter', sans-serif;
}
select._eli3_tas_input {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  padding-right: 32px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path fill='%23c9a227' d='M0 0l5 6 5-6z'/></svg>");
  background-repeat: no-repeat;
  background-position: right 12px center;
  cursor: pointer;
}
._eli3_tas_bool_label {
  display: flex;
  align-items: center;
  gap: 10px;
  font: 600 12.5px/1.3 'Inter', sans-serif;
  color: #0f172a;
  cursor: pointer;
}
._eli3_tas_bool_label input[type="checkbox"] {
  width: 16px;
  height: 16px;
  margin: 0;
  cursor: pointer;
  accent-color: #c9a227;
}

._eli3_tas_actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 14px 18px;
  background: linear-gradient(180deg, #faf9ee 0%, #f5f1d9 100%);
  border-top: 1px solid #fde68a;
}
._eli3_tas_btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 14px;
  font: 800 11px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  cursor: pointer;
  border-radius: 2px;
  transition: transform 0.12s, box-shadow 0.12s;
}
._eli3_tas_btn_primary {
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
}
._eli3_tas_btn_primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(21, 101, 192, 0.3);
}
._eli3_tas_btn_secondary {
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #cbd5e1;
}
._eli3_tas_btn_secondary:hover {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}

._eli3_tas_push_opt {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 18px 6px 18px;
  background: #fffbeb;
  border-top: 1px solid #fde68a;
  font: 400 12px/1.4 Inter, "Segoe UI", system-ui, sans-serif;
  color: #475569;
}
._eli3_tas_push_opt input[type="checkbox"] { margin-right: 7px; vertical-align: middle; }
._eli3_tas_push_opt span { font-weight: 700; color: #92400e; font-size: 11.5px; }
._eli3_tas_push_opt small { display: block; padding-left: 22px; color: #78716c; font-size: 10.5px; line-height: 1.4; }

._eli3_tas_pushlog {
  margin: 0;
  padding: 12px 18px;
  background: #0f172a;
  color: #cbd5e1;
  font: 400 11px/1.5 monospace;
  max-height: 200px;
  overflow-y: auto;
  border-top: 1px solid #1e293b;
}

/* Mode tabs in the top bar */
._eli3_tas_modetabs { display: flex; gap: 4px; margin-left: 16px; }
._eli3_tas_modetab {
  background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12);
  color: #cbd5e1; padding: 6px 14px; font: 700 11px/1 Inter, system-ui, sans-serif;
  letter-spacing: 0.06em; text-transform: uppercase; cursor: pointer;
}
._eli3_tas_modetab.active { background: #c9a227; color: #0f172a; border-color: #c9a227; }
._eli3_tas_modetab:hover:not(.active) { background: rgba(255,255,255,0.12); color: #fff; }

/* Sub-tabs inside the editor (Metadata / Code) */
._eli3_tas_subtabs {
  display: flex; gap: 2px; padding: 0 18px; background: #faf9ee;
  border-bottom: 1px solid #e6e2c8;
}
._eli3_tas_subtab {
  background: transparent; border: none; padding: 10px 14px;
  font: 700 11px/1 Inter, system-ui, sans-serif; color: #78716c;
  cursor: pointer; border-bottom: 2px solid transparent;
}
._eli3_tas_subtab.active { color: #92400e; border-bottom-color: #c9a227; }
._eli3_tas_subtab:hover:not(.active) { color: #1e293b; background: rgba(201,162,39,0.06); }

/* Code editor */
._eli3_tas_codenote {
  margin: 10px 18px 0 18px; padding: 9px 12px;
  background: #fef3c7; border: 1px solid #fde68a; border-left: 3px solid #f59e0b;
  font: 600 11px/1.5 Inter, system-ui, sans-serif; color: #92400e;
}
._eli3_tas_codeblock { padding: 10px 18px 0 18px; }
._eli3_tas_codelabel {
  font: 700 10px/1.2 Inter, system-ui, sans-serif; color: #475569;
  text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 4px;
}
._eli3_tas_codekey {
  font-family: monospace; color: #94a3b8; font-size: 9.5px; font-weight: 600;
  text-transform: none; letter-spacing: 0; margin-left: 6px;
}
._eli3_tas_codearea {
  width: 100%; min-height: 140px; max-height: 480px;
  padding: 10px 12px; box-sizing: border-box;
  background: #0f172a; color: #e2e8f0;
  font: 12px/1.5 "JetBrains Mono", Consolas, monospace;
  border: 1px solid #1e293b; resize: vertical; outline: none;
  tab-size: 2;
}
._eli3_tas_codearea:focus { border-color: #c9a227; box-shadow: 0 0 0 2px rgba(201,162,39,0.25); }

/* Admin Overrides + Default Ordering wrappers */
._eli3_tas_admin_wrap { padding: 0; overflow-y: auto; height: 100%; box-sizing: border-box; }
._eli3_tas_admin_intro {
  padding: 18px 22px 14px 22px; background: linear-gradient(180deg, #fffbeb 0%, #faf9ee 100%);
  border-bottom: 1px solid #e6e2c8;
}
._eli3_tas_admin_eyebrow {
  font: 800 10px/1 Inter, system-ui, sans-serif; color: #92400e;
  text-transform: uppercase; letter-spacing: 0.12em; margin-bottom: 6px;
}
._eli3_tas_admin_title {
  font: 800 22px/1.1 Inter, system-ui, sans-serif; color: #0f172a; margin-bottom: 8px;
}
._eli3_tas_admin_desc { font: 400 12.5px/1.55 Inter, system-ui, sans-serif; color: #475569; }
._eli3_tas_admin_desc code, ._eli3_tas_admin_actions_help code {
  font: 600 11.5px/1 monospace; background: rgba(201,162,39,0.1);
  padding: 1px 5px; border-radius: 2px; color: #92400e;
}
._eli3_tas_admin_actions_help { margin-top: 10px; font-size: 11.5px; color: #64748b; }
._eli3_tas_admin_split { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
._eli3_tas_admin_left, ._eli3_tas_admin_right { padding: 14px 18px; border-right: 1px solid #e6e2c8; }
._eli3_tas_admin_right { border-right: none; }
._eli3_tas_admin_list { display: flex; flex-direction: column; gap: 8px; }
._eli3_tas_admin_card {
  padding: 10px 12px; background: #fff; border: 1px solid #e2e8f0; border-left: 3px solid #c9a227;
  font: 400 11.5px/1.45 Inter, system-ui, sans-serif;
}
._eli3_tas_admin_card_head { font-weight: 700; color: #0f172a; margin-bottom: 4px; }
._eli3_tas_admin_card_aud  { color: #64748b; font-size: 10.5px; }
._eli3_tas_admin_card_acts { color: #92400e; font-weight: 600; font-size: 11px; }
._eli3_tas_admin_exp {
  font-size: 9.5px; font-weight: 700; color: #b91c1c; margin-left: 8px;
  background: #fef2f2; padding: 1px 5px; text-transform: uppercase; letter-spacing: 0.06em;
}
._eli3_tas_admin_card_remove { margin-top: 8px; font-size: 10px !important; padding: 4px 8px !important; }
._eli3_tas_admin_preview pre {
  background: #0f172a; color: #e2e8f0; padding: 12px;
  font: 11px/1.4 monospace; max-height: 320px; overflow: auto;
  border: 1px solid #1e293b;
}
